function check([grid], actual, expected) {
  const rows = grid.length;
  const cols = grid[0].length;
  if (!Array.isArray(actual) || actual.length !== rows) return false;
  for (const row of actual) {
    if (!Array.isArray(row) || row.length !== cols) return false;
    if (row.some(v => !Number.isInteger(v) || v < 1)) return false;
  }
  const largest = matrix => matrix.reduce((top, row) => row.reduce((a, b) => Math.max(a, b), top), 0);
  if (largest(actual) !== largest(expected)) return false;
  // Inside each row and each column, cells sorted by their original value must get strictly increasing new values.
  const increasing = cells => {
    cells.sort((a, b) => grid[a[0]][a[1]] - grid[b[0]][b[1]]);
    for (let k = 1; k < cells.length; k++) {
      const [r0, c0] = cells[k - 1];
      const [r1, c1] = cells[k];
      if (actual[r1][c1] <= actual[r0][c0]) return false;
    }
    return true;
  };
  for (let r = 0; r < rows; r++) if (!increasing(Array.from({ length: cols }, (_, c) => [r, c]))) return false;
  for (let c = 0; c < cols; c++) if (!increasing(Array.from({ length: rows }, (_, r) => [r, c]))) return false;
  return true;
}

