function validate([grid]) {
  const rows = grid.length;
  if (rows < 1 || rows > 1000) return 'grid needs 1 to 1000 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 1000) return 'Each row needs 1 to 1000 values.';
  if (grid.some(row => row.length !== cols)) return 'All rows must have the same length.';
  if (rows * cols > 100000) return 'grid holds at most 10^5 values.';
  const seen = new Set();
  for (const row of grid) {
    for (const v of row) {
      if (!Number.isInteger(v) || v < 1 || v > 1000000000) return 'Each value is an integer between 1 and 10^9.';
      if (seen.has(v)) return 'All values in grid must be distinct.';
      seen.add(v);
    }
  }
  return null;
}

