function minScore(grid) {
  // Start every cell at 1 and keep lifting any cell that is not above a smaller neighbour in its row or column.
  const rows = grid.length;
  const cols = grid[0].length;
  const out = grid.map(row => row.map(() => 1));
  let changed = true;
  while (changed) {
    changed = false;
    for (let r = 0; r < rows; r++)
      for (let c = 0; c < cols; c++) {
        for (let k = 0; k < cols; k++)
          if (grid[r][k] < grid[r][c] && out[r][k] >= out[r][c]) { out[r][c] = out[r][k] + 1; changed = true; }
        for (let k = 0; k < rows; k++)
          if (grid[k][c] < grid[r][c] && out[k][c] >= out[r][c]) { out[r][c] = out[k][c] + 1; changed = true; }
      }
  }
  return out;
}

