function generate(rand, size) {
  const large = size === 'large';
  const shape = rand();
  let rows, cols;
  if (large) {
    if (shape < 0.15) { rows = 1 + Math.floor(rand() * 3); cols = 100; }
    else if (shape < 0.3) { rows = 100; cols = 1 + Math.floor(rand() * 3); }
    else { rows = 60 + Math.floor(rand() * 41); cols = 60 + Math.floor(rand() * 41); }
  } else {
    rows = 1 + Math.floor(rand() * 4);
    cols = 1 + Math.floor(rand() * 4);
  }
  const count = rows * cols;
  // Distinct values: either a shuffled 1..count or random picks from a wide range.
  const values = new Set();
  if (rand() < 0.5) {
    for (let v = 1; v <= count; v++) values.add(v);
  } else {
    const span = large ? 1000000000 : 50;
    while (values.size < count) values.add(1 + Math.floor(rand() * span));
  }
  const list = [...values];
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  const grid = Array.from({ length: rows }, (_, r) => list.slice(r * cols, (r + 1) * cols));
  return [grid];
}
